const starterFiles = {

  "index.html": `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>My J-SYRO Project</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>

  <h1>Welcome to J-SYRO</h1>
  <p>Start writing your code here.</p>

  <script src="script.js"></script>
</body>
</html>`,

  "style.css": `body {
  margin: 0;
  padding: 40px;
  font-family: Arial, sans-serif;
  background: #f5f5f5;
  color: #222;
}`,

  "script.js": `console.log("J-SYRO project ready");`

};

const sharedProject = readSharedProject();
let currentProjectKey =
    localStorage.getItem(
        "j-syro-current-project-key"
    ) || "default";
const initialFiles = sharedProject?.files || loadFiles();
const initialFileNames = Object.keys(initialFiles);
const initialActiveFile = initialFileNames.includes("index.html") ? "index.html" : initialFileNames[0];

const state = {
  files: initialFiles,
  folders: sharedProject?.folders || loadFolders(),
  activeFile: initialActiveFile,
  openFiles: initialActiveFile ? [initialActiveFile] : [],
  dirty: new Set(),
  selectedFolder: "",
  expandedFolders: new Set(sharedProject?.folders || loadFolders()),
  inlineAction: null,
  contextTarget: null,
  pendingDelete: null
};

const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];
const editor = $("#codeEditor");
const lineNumbers = $("#lineNumbers");
const highlightLayer = $("#highlightLayer");
const highlightCode = $("#highlightCode");
const filesContainer = $("#filesContainer");
const tabs = $("#tabs");
const sidebar = $("#sidebar");
const workbench = $(".workbench");
const previewFrame = $("#previewFrame");
const workspaceLayout = $(".workspace");
let previewObjectUrl = null;

function readSharedProject() {
  try {
    const match = window.location.hash.match(/^#project=(.+)$/);
    if (!match) return null;
    const binary = atob(match[1]);
    const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
    const project = JSON.parse(new TextDecoder().decode(bytes));
    if (!project || typeof project.files !== "object" || !Array.isArray(project.folders)) return null;
    return project;
  } catch {
    return null;
  }
}

function loadFiles() {
  try {
    const currentProject = localStorage.getItem("j-syro-project");
    if (currentProject !== null) {
      const parsedProject = JSON.parse(currentProject);
      if (parsedProject && typeof parsedProject === "object" && !Array.isArray(parsedProject)) return parsedProject;
    }

    const legacyProject = localStorage.getItem("codluno-project");
    if (legacyProject !== null) {
      const migratedProject = JSON.parse(legacyProject);
      if (migratedProject && typeof migratedProject === "object" && Object.keys(migratedProject).length) {
        localStorage.setItem("j-syro-project", JSON.stringify(migratedProject));
        localStorage.removeItem("codluno-project");
        return migratedProject;
      }
    }

    const freshProject = { ...starterFiles };
    localStorage.setItem("j-syro-project", JSON.stringify(freshProject));
    return freshProject;
  } catch {
    return { ...starterFiles };
  }
}

function persistFiles() {
  try {
    localStorage.setItem("j-syro-project", JSON.stringify(state.files));
    localStorage.setItem("j-syro-folders", JSON.stringify(state.folders));
    return true;
  } catch {
    showToast("Files could not be saved in this browser");
    return false;
  }
}

function loadFolders() {
  try {
    const folders = JSON.parse(localStorage.getItem("j-syro-folders") || "[]");
    return Array.isArray(folders) ? folders : [];
  } catch {
    return [];
  }
}

function fileType(name) {
  const extension = name.split(".").pop().toLowerCase();
  return extension === "html" ? "html" : extension === "css" ? "css" : ["js", "mjs"].includes(extension) ? "js" : "text";
}

function fileBadge(name) {
  const type = fileType(name);
  return type === "html" ? "5" : type === "css" ? "#" : type === "js" ? "JS" : "·";
}

function renderFiles() {
  filesContainer.innerHTML = "";
  renderTreeLevel("", filesContainer, 0);
  if (state.inlineAction && state.inlineAction.kind === "create") appendInlineInput(state.inlineAction.parent, state.inlineAction.type, "");
  $$(".file-item[data-file]").forEach(item => item.addEventListener("click", () => openFile(item.dataset.file)));
  $$(".file-item[data-folder]").forEach(item => item.addEventListener("click", () => toggleFolder(item.dataset.folder)));
  $$(".file-item[data-file], .file-item[data-folder]").forEach(item => item.addEventListener("contextmenu", openTreeContextMenu));
  requestAnimationFrame(() => $(".inline-tree-input")?.focus());
}

function parentPath(path) {
  const pieces = path.split("/");
  pieces.pop();
  return pieces.join("/");
}

function baseName(path) {
  return path.split("/").pop();
}

function renderTreeLevel(parent, container, depth) {
  const folders = state.folders.filter(path => parentPath(path) === parent).sort();
  const files = Object.keys(state.files).filter(path => parentPath(path) === parent).sort();

  folders.forEach(path => {
    const row = document.createElement("div");
    row.className = `file-item ${state.selectedFolder === path ? "selected-folder" : ""}`;
    row.dataset.folder = path;
    row.dataset.type = "folder";
    row.style.paddingLeft = `${12 + depth * 14}px`;
    row.style.setProperty("--tree-depth", `${depth * 14}px`);
    row.innerHTML = `<span class="file-icon">${state.expandedFolders.has(path) ? "⌄" : "›"}</span><span class="tree-name">${escapeHtml(baseName(path))}</span>`;
    container.appendChild(row);
    if (state.inlineAction?.kind === "rename" && state.inlineAction.path === path) replaceNameWithInput(row, path, "folder");
    if (state.expandedFolders.has(path)) renderTreeLevel(path, container, depth + 1);
  });

  files.forEach(path => {
    const row = document.createElement("div");
    row.className = `file-item ${path === state.activeFile ? "active" : ""}`;
    row.dataset.file = path;
    row.dataset.type = fileType(path);
    row.style.paddingLeft = `${18 + depth * 14}px`;
    row.innerHTML = `<span class="file-icon">${fileBadge(path)}</span><span class="tree-name">${escapeHtml(baseName(path))}</span>`;
    container.appendChild(row);
    if (state.inlineAction?.kind === "rename" && state.inlineAction.path === path) replaceNameWithInput(row, path, "file");
  });
}

function toggleFolder(path) {
  state.selectedFolder = path;
  if (state.expandedFolders.has(path)) state.expandedFolders.delete(path);
  else state.expandedFolders.add(path);
  renderFiles();
}

function beginInlineCreate(type) {
  const parent = state.selectedFolder;
  if (parent) state.expandedFolders.add(parent);
  state.inlineAction = { kind: "create", type, parent };
  renderFiles();
}

function appendInlineInput(parent, type, value) {
  const depth = parent ? parent.split("/").length : 0;
  const input = document.createElement("input");
  input.className = "inline-tree-input";
  input.value = value;
  input.placeholder = type === "file" ? "filename.html" : "folder-name";
  input.style.marginLeft = `${8 + depth * 14}px`;
  input.addEventListener("keydown", event => {
    if (event.key === "Enter") commitInlineAction(input.value);
    if (event.key === "Escape") cancelInlineAction();
  });
  input.addEventListener("blur", () => setTimeout(() => { if (state.inlineAction) cancelInlineAction(); }, 120));
  filesContainer.appendChild(input);
}

function replaceNameWithInput(row, path, type) {
  const nameElement = row.querySelector(".tree-name");
  const input = document.createElement("input");
  input.className = "inline-tree-input";
  input.value = baseName(path);
  input.addEventListener("click", event => event.stopPropagation());
  input.addEventListener("keydown", event => {
    event.stopPropagation();
    if (event.key === "Enter") commitInlineAction(input.value);
    if (event.key === "Escape") cancelInlineAction();
  });
  input.addEventListener("blur", () => setTimeout(() => { if (state.inlineAction) cancelInlineAction(); }, 120));
  nameElement.replaceWith(input);
  requestAnimationFrame(() => { input.focus(); input.select(); });
}

function renderTabs() {
  state.openFiles = state.openFiles.filter(name => Object.prototype.hasOwnProperty.call(state.files, name));
  tabs.innerHTML = state.openFiles.map(name => `<button class="tab ${name === state.activeFile ? "active" : ""}" data-file="${escapeHtml(name)}" role="tab" aria-selected="${name === state.activeFile}"><span class="file-icon">${fileBadge(name)}</span><span class="tab-name">${escapeHtml(name)}</span>${state.dirty.has(name) ? '<span class="dirty">•</span>' : ""}<span class="tab-close" title="Close">×</span></button>`).join("");
  $$(".tab").forEach(tab => {
    tab.addEventListener("click", () => openFile(tab.dataset.file));
    tab.querySelector(".tab-close").addEventListener("click", event => { event.stopPropagation(); closeTab(tab.dataset.file); });
  });
}

function openFile(name) {
  if (!name || !Object.prototype.hasOwnProperty.call(state.files, name)) return;
  editor.disabled = false;
  editor.placeholder = "Write your code here...";
  state.activeFile = name;
  if (!state.openFiles.includes(name)) state.openFiles.push(name);
  editor.value = state.files[name];
  editor.setSelectionRange(0, 0);
  editor.scrollTop = 0;
  editor.scrollLeft = 0;
  lineNumbers.scrollTop = 0;
  highlightLayer.scrollTop = 0;
  highlightLayer.scrollLeft = 0;
  $("#breadcrumbFile").textContent = name;
  $("#languageMode").textContent = fileType(name).toUpperCase();
  renderFiles();
  renderTabs();
  updateLineNumbers();
  updateHighlighting();
  updateCursor();
  editor.focus();
  requestAnimationFrame(() => {
    editor.scrollTop = 0;
    editor.scrollLeft = 0;
    lineNumbers.scrollTop = 0;
    highlightLayer.scrollTop = 0;
    highlightLayer.scrollLeft = 0;
  });
}

function showEmptyEditor() {
  state.activeFile = null;
  state.openFiles = [];
  editor.value = "";
  editor.disabled = true;
  editor.placeholder = "Create a file to start coding";
  $("#breadcrumbFile").textContent = "No file open";
  $("#languageMode").textContent = "TEXT";
  $("#cursorPosition").textContent = "Ln 1, Col 1";
  lineNumbers.innerHTML = "";
  highlightCode.innerHTML = "";
  renderFiles();
  renderTabs();
}

function closeTab(name) {
  if (state.openFiles.length === 1) return showToast("Keep at least one file open");
  const index = state.openFiles.indexOf(name);
  state.openFiles = state.openFiles.filter(file => file !== name);
  if (state.activeFile === name) openFile(state.openFiles[Math.max(0, index - 1)]);
  else renderTabs();
}

function cancelInlineAction() {
  state.inlineAction = null;
  renderFiles();
}

function validTreeName(name) {
  return Boolean(name) && name !== "." && name !== ".." && !/[\\/:*?"<>|]/.test(name);
}

function commitInlineAction(rawName) {
  if (!state.inlineAction) return;
  const name = rawName.trim();
  if (!validTreeName(name)) {
    showToast("Enter a valid name");
    return cancelInlineAction();
  }

  const action = state.inlineAction;
  if (action.kind === "create") {
    const path = action.parent ? `${action.parent}/${name}` : name;
    const exists = [...Object.keys(state.files), ...state.folders].some(item => item.toLowerCase() === path.toLowerCase());
    if (exists) {
      showToast("An item with that name already exists");
      return cancelInlineAction();
    }
    state.inlineAction = null;
    if (action.type === "folder") {
      state.folders.push(path);
      state.selectedFolder = path;
      state.expandedFolders.add(path);
    } else {
      state.files[path] = fileType(path) === "html" ? "<!DOCTYPE html>\n<html>\n<body>\n\n</body>\n</html>" : "";
      state.openFiles.push(path);
      persistFiles();
      openFile(path);
      showToast(`${name} created`);
      return;
    }
    persistFiles();
    renderFiles();
    showToast(`${name} created`);
    return;
  }

  renameTreeItem(action.type, action.path, name);
}

function renameTreeItem(type, oldPath, newName) {
  const parent = parentPath(oldPath);
  const newPath = parent ? `${parent}/${newName}` : newName;
  if (newPath === oldPath) return cancelInlineAction();
  const exists = [...Object.keys(state.files), ...state.folders].some(item => item.toLowerCase() === newPath.toLowerCase());
  if (exists) {
    showToast("An item with that name already exists");
    return cancelInlineAction();
  }

  if (type === "file") {
    state.files[newPath] = state.files[oldPath];
    delete state.files[oldPath];
    state.openFiles = state.openFiles.map(path => path === oldPath ? newPath : path);
    if (state.activeFile === oldPath) state.activeFile = newPath;
    if (state.dirty.has(oldPath)) { state.dirty.delete(oldPath); state.dirty.add(newPath); }
  } else {
    const replacePrefix = path => path === oldPath || path.startsWith(`${oldPath}/`) ? newPath + path.slice(oldPath.length) : path;
    state.folders = state.folders.map(replacePrefix);
    const renamedFiles = {};
    Object.entries(state.files).forEach(([path, content]) => { renamedFiles[replacePrefix(path)] = content; });
    state.files = renamedFiles;
    state.openFiles = state.openFiles.map(replacePrefix);
    state.activeFile = replacePrefix(state.activeFile);
    state.selectedFolder = newPath;
    state.expandedFolders = new Set([...state.expandedFolders].map(replacePrefix));
  }

  state.inlineAction = null;
  persistFiles();
  openFile(state.activeFile);
  showToast(`${baseName(oldPath)} renamed to ${newName}`);
}

function openTreeContextMenu(event) {
  event.preventDefault();
  event.stopPropagation();
  const row = event.currentTarget;
  state.contextTarget = row.dataset.file ? { type: "file", path: row.dataset.file } : { type: "folder", path: row.dataset.folder };
  if (state.contextTarget.type === "file") openFile(state.contextTarget.path);
  else state.selectedFolder = state.contextTarget.path;
  const menu = $("#fileContextMenu");
  menu.classList.add("open");
  menu.setAttribute("aria-hidden", "false");
  const menuWidth = 150;
  const menuHeight = 70;
  menu.style.left = `${Math.min(event.clientX, window.innerWidth - menuWidth - 8)}px`;
  menu.style.top = `${Math.min(event.clientY, window.innerHeight - menuHeight - 8)}px`;
}

function closeTreeContextMenu() {
  const menu = $("#fileContextMenu");
  menu.classList.remove("open");
  menu.setAttribute("aria-hidden", "true");
}

function deleteTreeItem(type, path) {
  const affectedFiles = type === "folder" ? Object.keys(state.files).filter(file => file.startsWith(`${path}/`)) : [path];
  const detail = type === "folder" ? `folder "${baseName(path)}" and everything inside it` : `"${baseName(path)}"`;
  state.pendingDelete = { type, path, affectedFiles };
  $("#deleteConfirmMessage").textContent = `Delete ${detail}? This action cannot be undone.`;
  $("#deleteConfirmModal").classList.add("open");
  $("#deleteConfirmModal").setAttribute("aria-hidden", "false");
  $("#confirmDelete").focus();
}

function cancelDelete() {
  state.pendingDelete = null;
  $("#deleteConfirmModal").classList.remove("open");
  $("#deleteConfirmModal").setAttribute("aria-hidden", "true");
}

function confirmDeleteItem() {
  if (!state.pendingDelete) return;
  const { type, path, affectedFiles } = state.pendingDelete;
  cancelDelete();

  affectedFiles.forEach(file => { delete state.files[file]; state.dirty.delete(file); });
  state.openFiles = state.openFiles.filter(file => !affectedFiles.includes(file));
  if (type === "folder") {
    state.folders = state.folders.filter(folder => folder !== path && !folder.startsWith(`${path}/`));
    state.expandedFolders = new Set([...state.expandedFolders].filter(folder => folder !== path && !folder.startsWith(`${path}/`)));
    if (state.selectedFolder === path || state.selectedFolder.startsWith(`${path}/`)) state.selectedFolder = parentPath(path);
  }
  if (affectedFiles.includes(state.activeFile)) {
    state.activeFile = state.openFiles[0] || Object.keys(state.files)[0] || null;
    if (state.activeFile && !state.openFiles.includes(state.activeFile)) state.openFiles.push(state.activeFile);
  }
  persistFiles();
  if (state.activeFile) openFile(state.activeFile);
  else showEmptyEditor();
  showToast(`${baseName(path)} deleted`);
}

function updateLineNumbers() {
  const count = Math.max(1, editor.value.split("\n").length);
  lineNumbers.innerHTML = Array.from({ length: count }, (_, index) => index + 1).join("<br>");
}

function updateHighlighting() {
  const source = editor.value;
  const type = fileType(state.activeFile);
  highlightCode.innerHTML = highlightSource(source, type) + (source.endsWith("\n") ? " " : "");
}

function highlightSource(source, type) {
  if (type === "html") {
    return highlightHtml(source);
  }
  if (type === "css") {
    return tokenize(source, /\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|#[0-9a-fA-F]{3,8}\b|\b(?:rgb|rgba|hsl|hsla|var|calc|clamp|min|max|linear-gradient|radial-gradient)\b(?=\()|!?\b(?:important|inherit|initial|unset|auto|none|transparent|currentColor|solid|relative|absolute|fixed|flex|grid|block|inline|center)\b|-?\d*\.?\d+(?:px|rem|em|vh|vw|vmin|vmax|%|s|ms|deg|fr)?\b|--[\w-]+|[\w-]+(?=\s*:)|[^{}]+(?=\s*\{)/gi, (token, offset, fullSource) => {
      if (token.startsWith("/*")) return wrap("comment", token);
      if (/^["']/.test(token)) return wrap("value", token);
      if (/^#[\da-f]{3,8}$/i.test(token)) return wrap("value", token);
      if (/^-?\d/.test(token.trim())) return wrap(/[a-z%]+$/i.test(token) ? "unit" : "number", token);
      if (/^(rgb|rgba|hsl|hsla|var|calc|clamp|min|max|linear-gradient|radial-gradient)$/i.test(token)) return wrap("function", token);
      if (/^(!?important|inherit|initial|unset|auto|none|transparent|currentColor|solid|relative|absolute|fixed|flex|grid|block|inline|center)$/i.test(token)) return wrap("constant", token);
      if (token.startsWith("--")) return wrap("variable", token);
      if (/^[\w-]+$/.test(token.trim())) return wrap("property", token);
      return wrap("selector", token);
    });
  }
  if (type === "js") {
    const keywords = new Set(["const","let","var","function","return","if","else","for","while","do","switch","case","break","continue","class","new","this","extends","import","from","export","default","async","await","try","catch","finally","throw","typeof","instanceof","in","of","delete","yield","static","get","set"]);
    const constants = new Set(["true","false","null","undefined","NaN","Infinity"]);
    const builtins = new Set(["document","window","console","Array","Object","String","Number","Boolean","Math","Date","JSON","Promise","Set","Map","Error","fetch","localStorage","setTimeout","setInterval"]);
    return tokenize(source, /\/\/[^\n]*|\/\*[\s\S]*?\*\/|`(?:\\.|[^`\\])*`|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b\d+(?:\.\d+)?\b|===|!==|=>|==|!=|<=|>=|&&|\|\||\?\?|\+\+|--|\*\*|[+\-*\/%=<>!?&|]+|\b[A-Za-z_$][\w$]*\b/g, (token, offset, fullSource) => {
      if (token.startsWith("//") || token.startsWith("/*")) return wrap("comment", token);
      if (/^["']/.test(token)) return wrap("string", token);
      if (token.startsWith("`")) return wrap("value", token);
      if (/^\d/.test(token)) return wrap("number", token);
      if (keywords.has(token)) return wrap("keyword", token);
      if (constants.has(token)) return wrap("constant", token);
      if (builtins.has(token)) return wrap("builtin", token);
      if (/^[+\-*\/%=<>!?&|]+$/.test(token)) return wrap("operator", token);
      const before = fullSource.slice(0, offset);
      const after = fullSource.slice(offset + token.length);
      if (/^\s*\(/.test(after)) return wrap("function", token);
      if (/\.\s*$/.test(before)) return wrap("property", token);
      return wrap("variable", token);
    });
  }
  return escapeHtml(source);
}

function highlightHtml(source) {
  const pattern = /<script\b[^>]*>[\s\S]*?<\/script\s*>|<style\b[^>]*>[\s\S]*?<\/style\s*>|<!--[\s\S]*?-->|<!DOCTYPE[^>]*>|<\/?[A-Za-z][^>]*>|&[A-Za-z0-9#]+;/gi;
  return tokenize(source, pattern, token => {
    if (token.startsWith("<!--")) return wrap("comment", token);
    if (/^<!doctype/i.test(token)) return wrap("keyword", token);
    if (token.startsWith("&")) return wrap("constant", token);

    const scriptBlock = token.match(/^(<script\b[^>]*>)([\s\S]*)(<\/script\s*>)$/i);
    if (scriptBlock) {
      return highlightHtmlTag(scriptBlock[1]) + highlightSource(scriptBlock[2], "js") + highlightHtmlTag(scriptBlock[3]);
    }

    const styleBlock = token.match(/^(<style\b[^>]*>)([\s\S]*)(<\/style\s*>)$/i);
    if (styleBlock) {
      return highlightHtmlTag(styleBlock[1]) + highlightSource(styleBlock[2], "css") + highlightHtmlTag(styleBlock[3]);
    }

    return highlightHtmlTag(token);
  });
}

function highlightHtmlTag(tag) {
  const match = tag.match(/^<(\/?)\s*([\w:-]+)([\s\S]*?)(\/?)>$/);
  if (!match) return escapeHtml(tag);

  const [, closingSlash, tagName, attributes, selfClosingSlash] = match;
  let output = wrap("punctuation", "<" + closingSlash) + wrap("tag", tagName);
  let lastIndex = 0;
  const attributePattern = /(\s+)([\w:-]+)(\s*=\s*)("[^"]*"|'[^']*'|[^\s>]+)/g;
  let attributeMatch;

  while ((attributeMatch = attributePattern.exec(attributes)) !== null) {
    output += escapeHtml(attributes.slice(lastIndex, attributeMatch.index));
    output += attributeMatch[1];
    output += wrap("attribute", attributeMatch[2]);
    output += wrap("operator", attributeMatch[3]);
    output += wrap("value", attributeMatch[4]);
    lastIndex = attributeMatch.index + attributeMatch[0].length;
  }

  const remainder = attributes.slice(lastIndex);
  output += escapeHtml(remainder).replace(/([\w:-]+)/g, '<span class="token-attribute">$1</span>');
  output += wrap("punctuation", selfClosingSlash + ">");
  return output;
}

function tokenize(source, pattern, decorate) {
  let output = "";
  let lastIndex = 0;
  source.replace(pattern, (match, ...args) => {
    const offset = args[args.length - 2];
    output += escapeHtml(source.slice(lastIndex, offset)) + decorate(match, offset, source);
    lastIndex = offset + match.length;
    return match;
  });
  return output + escapeHtml(source.slice(lastIndex));
}

function wrap(type, value) {
  return `<span class="token-${type}">${escapeHtml(value)}</span>`;
}

function updateCursor() {
  const beforeCursor = editor.value.slice(0, editor.selectionStart).split("\n");
  const currentLine = beforeCursor[beforeCursor.length - 1];
  $("#cursorPosition").textContent = `Ln ${beforeCursor.length}, Col ${currentLine.length + 1}`;
}
/* =========================
   SAVE PROJECT TO SUPABASE
========================= */

async function saveProjectToCloud() {
    const saveButton =
        document.getElementById("saveBtn");

    const projectNameText =
        document.getElementById(
            "projectNameText"
        );

    const originalButtonHTML =
        saveButton
            ? saveButton.innerHTML
            : "";

    try {

        if (state.activeFile) {
            state.files[state.activeFile] =
                editor.value;
        }

        persistFiles();

        if (
            typeof workspaceSupabase ===
                "undefined" ||
            !workspaceSupabase
        ) {
            throw new Error(
                "Supabase is not connected."
            );
        }

        const {
            data: userData,
            error: userError
        } =
            await workspaceSupabase
                .auth
                .getUser();

        if (userError) {
            throw userError;
        }

        if (!userData.user) {
            throw new Error(
                "Please log in again."
            );
        }

        if (saveButton) {
            saveButton.disabled = true;

            saveButton.innerHTML =
                "<span>◌</span>" +
                '<span class="action-label">' +
                "Saving..." +
                "</span>";
        }

        const projectName =
            projectNameText
                ?.textContent
                .trim() ||
            "untitled-project";

        const { error } =
            await workspaceSupabase
                .from("projects")
                .upsert(
                    {
                        user_id:
                            userData.user.id,

                        project_key:
                            currentProjectKey,

                        name:
                            projectName,

                        files:
                            state.files,

                        folders:
                            state.folders,

                        updated_at:
                            new Date()
                                .toISOString()
                    },
                    {
                        onConflict:
                            "user_id,project_key"
                    }
                );

        if (error) {
            throw error;
        }

        state.dirty.clear();

        renderTabs();

        showToast(
            "Project saved to your account"
        );

    } catch (error) {

        console.error(
            "Cloud save error:",
            error
        );

        showToast(
            error.message ||
            "Project could not be saved"
        );
        /* Automatically create history snapshot */


    } finally {

        if (saveButton) {
            saveButton.disabled = false;

            saveButton.innerHTML =
                originalButtonHTML;
        }
    }
}

function saveProject(showMessage = true) {
  if (!state.activeFile) return showToast("Create a file before saving");
  state.files[state.activeFile] = editor.value;
  persistFiles();
  state.dirty.clear();
  renderTabs();
  $("#saveState").textContent = "All changes saved";
  if (showMessage) showToast("Project saved locally");
}
/* =========================
   LOAD PROJECT FROM CLOUD
========================= */

async function loadProjectFromCloud() {

    try {

        /* Supabase ready hone ka wait */

        for (let attempt = 0; attempt < 50; attempt++) {

            if (
                typeof workspaceSupabase !== "undefined" &&
                workspaceSupabase
            ) {
                break;
            }

            await new Promise(resolve =>
                setTimeout(resolve, 100)
            );
        }


        if (
            typeof workspaceSupabase === "undefined" ||
            !workspaceSupabase
        ) {
            console.error("Supabase is not ready.");
            return;
        }


        /* Logged-in user check */

        const {
            data: sessionData,
            error: sessionError
        } = await workspaceSupabase.auth.getSession();


        if (sessionError || !sessionData.session) {
            return;
        }


        const user = sessionData.session.user;


        /* User ka saved project lao */

        const {
            data: project,
            error
        } = await workspaceSupabase
            .from("projects")
            .select("name, files, folders")
            .eq("user_id", user.id)
            .eq("project_key", currentProjectKey)
            .maybeSingle();


        if (error) {
            throw error;
        }


        if (!project) {
            console.log("No cloud project found.");
            return;
        }


        /* Saved files workspace mein lagao */

        if (
            project.files &&
            typeof project.files === "object" &&
            !Array.isArray(project.files)
        ) {
            state.files = project.files;
        }


        state.folders =
            Array.isArray(project.folders)
                ? project.folders
                : [];


        const fileNames =
            Object.keys(state.files);


        state.activeFile =
            fileNames.includes("index.html")
                ? "index.html"
                : fileNames[0] || null;


        state.openFiles =
            state.activeFile
                ? [state.activeFile]
                : [];


        state.dirty.clear();

        state.selectedFolder = "";

        state.expandedFolders =
            new Set(state.folders);


        /* Browser backup bhi update */

        persistFiles();


        /* Workspace refresh */

        renderFiles();
        renderTabs();


        if (state.activeFile) {
            openFile(state.activeFile);
        } else {
            showEmptyEditor();
        }


        const projectTitle =
            document.querySelector(
                ".project-title span:last-child"
            );


        if (projectTitle && project.name) {
            projectTitle.textContent =
                project.name;
        }


        showToast("Cloud project loaded");


    } catch (error) {

        console.error(
            "Cloud load error:",
            error
        );

        showToast(
            "Cloud project could not be loaded"
        );
    }
}

async function saveFileWithPicker() {
  if (!state.activeFile) return showToast("Create a file before saving");
  state.files[state.activeFile] = editor.value;
  saveProject(false);

  const type = fileType(state.activeFile);
  const fileOptions = {
    html: { description: "HTML document", mime: "text/html", extension: ".html" },
    css: { description: "CSS stylesheet", mime: "text/css", extension: ".css" },
    js: { description: "JavaScript file", mime: "text/javascript", extension: ".js" },
    text: { description: "Text document", mime: "text/plain", extension: ".txt" }
  };
  const option = fileOptions[type] || fileOptions.text;
  const nameExtension = state.activeFile.includes(".") ? `.${state.activeFile.split(".").pop().toLowerCase()}` : option.extension;
  const safeExtension = /^\.[a-z0-9]{1,12}$/i.test(nameExtension) ? nameExtension : option.extension;

  if (typeof window.showSaveFilePicker === "function") {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: state.activeFile,
        types: [{
          description: option.description,
          accept: { [option.mime]: [safeExtension] }
        }]
      });
      const writable = await handle.createWritable();
      await writable.write(editor.value);
      await writable.close();
      showToast(`${state.activeFile} saved`);
      return;
    } catch (error) {
      if (error && error.name === "AbortError") {
        showToast("Save cancelled");
        return;
      }
    }
  }

  downloadCurrentFile();
}

