function formatDocument() {
  if (!state.activeFile) return showToast("Create a file before formatting");
  const type = fileType(state.activeFile);
  if (type === "text") return showToast("Formatting is not available for this file");
  editor.value = editor.value.replace(/\t/g, "  ").replace(/[ \t]+$/gm, "").replace(/\n{3,}/g, "\n\n").trim() + "\n";
  state.files[state.activeFile] = editor.value;
  state.dirty.add(state.activeFile);
  updateLineNumbers();
  updateHighlighting();
  renderTabs();
  showToast("Document formatted");
}

let toastTimer;
function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 2200);
}

function escapeHtml(value) {
  return value.replace(/[&<>"]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[character]);
}

editor.addEventListener("input", () => {

    if (!state.activeFile) {
        return;
    }

    state.files[state.activeFile] =
        editor.value;

    state.dirty.add(
        state.activeFile
    );


    const saveStateElement =
        document.getElementById(
            "saveState"
        );

    if (saveStateElement) {
        saveStateElement.textContent =
            "Unsaved changes";
    }


    updateLineNumbers();

    updateHighlighting();

    renderTabs();

});
editor.addEventListener("scroll", () => {
  lineNumbers.scrollTop = editor.scrollTop;
  highlightLayer.scrollTop = editor.scrollTop;
  highlightLayer.scrollLeft = editor.scrollLeft;
});
editor.addEventListener("keyup", updateCursor);
editor.addEventListener("click", updateCursor);
editor.addEventListener("keydown", event => {
  if (event.key === "Tab") {
    event.preventDefault();
    const start = editor.selectionStart;
    editor.setRangeText("  ", start, editor.selectionEnd, "end");
    editor.dispatchEvent(new Event("input"));
  }
});

