/* =========================
   CODE AREA DARK / LIGHT THEME
========================= */

function initializeCodeAreaTheme() {
    const themeButton =
        document.getElementById("themeToggleBtn");

    const themeIcon =
        document.getElementById("themeToggleIcon");

    const themeText =
        document.getElementById("themeToggleText");

    const codeArea =
        document.querySelector(".code-wrapper");


    if (!themeButton || !codeArea) {
        console.error(
            "Theme button or code area was not found."
        );

        return;
    }


    /* Purane theme classes remove */

    document.body.classList.remove(
        "light-theme"
    );

    document
        .querySelector(".editor-pane")
        ?.classList.remove(
            "editor-light-theme"
        );


    function applyCodeAreaTheme(theme) {
        const lightTheme =
            theme === "light";


        codeArea.classList.toggle(
            "code-light-theme",
            lightTheme
        );


        if (themeIcon) {
            themeIcon.textContent =
                lightTheme ? "☾" : "☀";
        }


        if (themeText) {
            themeText.textContent =
                lightTheme ? "Dark" : "Light";
        }


        themeButton.title =
            lightTheme
                ? "Switch code area to dark"
                : "Switch code area to light";


        localStorage.setItem(
            "jSyroCodeTheme",
            lightTheme ? "light" : "dark"
        );
    }


    const savedTheme =
        localStorage.getItem(
            "jSyroCodeTheme"
        );


    applyCodeAreaTheme(
        savedTheme === "light"
            ? "light"
            : "dark"
    );


    themeButton.addEventListener(
        "click",
        function () {
            const currentlyLight =
                codeArea.classList.contains(
                    "code-light-theme"
                );


            applyCodeAreaTheme(
                currentlyLight
                    ? "dark"
                    : "light"
            );
        }
    );
}


initializeCodeAreaTheme();

