/* =========================
   MY PROJECTS
========================= */

function initializeMyProjects() {

    const myProjectsBtn =
        document.getElementById(
            "myProjectsBtn"
        );

    const projectsModal =
        document.getElementById(
            "projectsModal"
        );

    const projectsList =
        document.getElementById(
            "projectsList"
        );

    const closeProjectsBtn =
        document.getElementById(
            "closeProjectsModal"
        );

    if (
        !myProjectsBtn ||
        !projectsModal ||
        !projectsList
    ) {
        console.error(
            "My Projects elements missing"
        );

        return;
    }

    if (
        myProjectsBtn.dataset.ready ===
        "true"
    ) {
        return;
    }

    myProjectsBtn.dataset.ready =
        "true";


    function closeProjectsModal() {

        projectsModal.classList.remove(
            "open"
        );

        projectsModal.setAttribute(
            "aria-hidden",
            "true"
        );
    }


    async function getLoggedInUser() {

        const {
            data,
            error
        } =
            await workspaceSupabase
                .auth
                .getUser();

        if (error) {
            throw error;
        }

        if (!data.user) {
            throw new Error(
                "Please log in again"
            );
        }

        return data.user;
    }


    async function loadProjects() {

        projectsList.innerHTML =
            '<p class="panel-hint">' +
            "Loading projects..." +
            "</p>";

        try {

            const user =
                await getLoggedInUser();

            const {
                data: projects,
                error
            } =
                await workspaceSupabase
                    .from("projects")
                    .select(
                        "project_key,name,updated_at"
                    )
                    .eq(
                        "user_id",
                        user.id
                    )
                    .order(
                        "updated_at",
                        {
                            ascending: false
                        }
                    );

            if (error) {
                throw error;
            }

            projectsList.innerHTML = "";

            if (
                !projects ||
                projects.length === 0
            ) {
                projectsList.innerHTML =
                    '<p class="panel-hint">' +
                    "No projects found." +
                    "</p>";

                return;
            }


            projects.forEach(
                function (project) {

                    const row =
                        document.createElement(
                            "div"
                        );

                    row.className =
                        "project-list-item";

                    if (
                        project.project_key ===
                        currentProjectKey
                    ) {
                        row.classList.add(
                            "active"
                        );
                    }


                    const openButton =
                        document.createElement(
                            "button"
                        );

                    openButton.type =
                        "button";

                    openButton.className =
                        "project-open-button";


                    const name =
                        document.createElement(
                            "strong"
                        );

                    name.textContent =
                        project.name ||
                        "untitled-project";


                    const status =
                        document.createElement(
                            "span"
                        );

                    status.textContent =
                        project.project_key ===
                        currentProjectKey
                            ? "Currently open"
                            : "Click to open";


                    openButton.append(
                        name,
                        status
                    );


                    openButton.addEventListener(
                        "click",
                        async function () {

                            if (
                                project.project_key ===
                                currentProjectKey
                            ) {
                                closeProjectsModal();
                                return;
                            }

                            await saveProjectToCloud();

                            currentProjectKey =
                                project.project_key;

                            localStorage.setItem(
                                "j-syro-current-project-key",
                                currentProjectKey
                            );

                            window.location.reload();
                        }
                    );


                    const deleteButton =
                        document.createElement(
                            "button"
                        );

                    deleteButton.type =
                        "button";

                    deleteButton.className =
                        "project-delete-button";

                    deleteButton.textContent =
                        "Delete";


                    deleteButton.addEventListener(
                        "click",
                        async function () {

                            const projectName =
                                project.name ||
                                "untitled-project";

                            const confirmed =
                                window.confirm(
                                    `Delete "${projectName}" permanently?`
                                );

                            if (!confirmed) {
                                return;
                            }

                            deleteButton.disabled =
                                true;

                            deleteButton.textContent =
                                "Deleting...";

                            try {

                                const {
                                    error: deleteError
                                } =
                                    await workspaceSupabase
                                        .from(
                                            "projects"
                                        )
                                        .delete()
                                        .eq(
                                            "user_id",
                                            user.id
                                        )
                                        .eq(
                                            "project_key",
                                            project
                                                .project_key
                                        );

                                if (deleteError) {
                                    throw deleteError;
                                }


                                if (
                                    project.project_key ===
                                    currentProjectKey
                                ) {

                                    const remainingProjects =
                                        projects.filter(
                                            item =>
                                                item.project_key !==
                                                project.project_key
                                        );

                                    if (
                                        remainingProjects
                                            .length > 0
                                    ) {
                                        localStorage.setItem(
                                            "j-syro-current-project-key",
                                            remainingProjects[0]
                                                .project_key
                                        );

                                    } else {

                                        const newKey =
                                            window.crypto &&
                                            typeof window.crypto
                                                .randomUUID ===
                                                "function"
                                                ? window.crypto
                                                    .randomUUID()
                                                : `project-${Date.now()}`;

                                        localStorage.setItem(
                                            "j-syro-current-project-key",
                                            newKey
                                        );

                                        localStorage.setItem(
                                            "j-syro-project",
                                            JSON.stringify({
                                                ...starterFiles
                                            })
                                        );

                                        localStorage.setItem(
                                            "j-syro-folders",
                                            "[]"
                                        );
                                    }

                                    window.location.reload();
                                    return;
                                }


                                showToast(
                                    "Project deleted"
                                );

                                await loadProjects();

                            } catch (error) {

                                console.error(
                                    "Project delete error:",
                                    error
                                );

                                showToast(
                                    error.message ||
                                    "Project could not be deleted"
                                );

                                deleteButton.disabled =
                                    false;

                                deleteButton.textContent =
                                    "Delete";
                            }
                        }
                    );


                    row.append(
                        openButton,
                        deleteButton
                    );

                    projectsList.appendChild(
                        row
                    );
                }
            );

        } catch (error) {

            console.error(
                "My Projects error:",
                error
            );

            projectsList.innerHTML =
                '<p class="panel-hint">' +
                (
                    error.message ||
                    "Projects could not be loaded"
                ) +
                "</p>";
        }
    }


    async function openProjectsModal() {

        projectsModal.classList.add(
            "open"
        );

        projectsModal.setAttribute(
            "aria-hidden",
            "false"
        );

        await loadProjects();
    }


    myProjectsBtn.addEventListener(
        "click",
        openProjectsModal
    );


    closeProjectsBtn?.addEventListener(
        "click",
        closeProjectsModal
    );


    projectsModal.addEventListener(
        "click",
        function (event) {

            if (
                event.target ===
                projectsModal
            ) {
                closeProjectsModal();
            }
        }
    );
}


if (
    document.readyState === "loading"
) {
    document.addEventListener(
        "DOMContentLoaded",
        initializeMyProjects
    );
} else {
    initializeMyProjects();
}
/* =========================
   USER PLAN ACCESS
========================= */

window.jSyroAccess = {
    plan: "free",
    role: "user",
    status: "active",
    isAdmin: false,
    hasPro: false,
    hasBusiness: false,
    hasWorkApps: false,
    hasAllAccess: false
};


async function initializeUserPlan() {

    const planBadge =
        document.getElementById(
            "userPlanBadge"
        );

    if (!planBadge) {
        console.error(
            "User plan badge not found"
        );
        return;
    }


    try {

        if (
            typeof workspaceSupabase ===
                "undefined" ||
            !workspaceSupabase
        ) {
            throw new Error(
                "Supabase is not connected"
            );
        }


        const {
            data: userData,
            error: userError
        } =
            await workspaceSupabase
                .auth
                .getUser();


        if (userError) {
            throw userError;
        }


        if (!userData.user) {
            throw new Error(
                "User is not logged in"
            );
        }


        const {
            data: planData,
            error: planError
        } =
            await workspaceSupabase
                .from("user_plans")
                .select(
                    "plan,status,role,expires_at"
                )
                .eq(
                    "user_id",
                    userData.user.id
                )
                .maybeSingle();


        if (planError) {
            throw planError;
        }


        const plan =
            String(
                planData?.plan ||
                "free"
            )
                .trim()
                .toLowerCase();


        const role =
            String(
                planData?.role ||
                "user"
            )
                .trim()
                .toLowerCase();


        const status =
            String(
                planData?.status ||
                "active"
            )
                .trim()
                .toLowerCase();


        const expiryDate =
            planData?.expires_at
                ? new Date(
                    planData.expires_at
                )
                : null;


        const isExpired =
            expiryDate &&
            expiryDate.getTime() <
                Date.now();


        const isAdmin =
            role === "admin";


        const isActive =
            status === "active" &&
            !isExpired;


        /*
         * IMPORTANT:
         *
         * PRO
         * → only PRO
         *
         * BUSINESS
         * → only BUSINESS
         *
         * WORK APPS
         * → only WORK APPS
         *
         * ALL ACCESS
         * → everything
         *
         * ADMIN
         * → everything
         *
         * A paid plan does NOT unlock
         * the other paid plans.
         */

        const hasPro =
            isAdmin ||
            (
                isActive &&
                plan === "pro"
            );


        const hasBusiness =
            isAdmin ||
            (
                isActive &&
                plan === "business"
            );


        const hasWorkApps =
            isAdmin ||
            (
                isActive &&
                (
                    plan === "work_apps" ||
                    plan === "workapps" ||
                    plan === "work-apps"
                )
            );


        const hasAllAccess =
            isAdmin ||
            (
                isActive &&
                (
                    plan === "all_access" ||
                    plan === "all-access" ||
                    plan === "allaccess"
                )
            );


        window.jSyroAccess = {
            plan,
            role,
            status,
            isAdmin,
            hasPro,
            hasBusiness,
            hasWorkApps,
            hasAllAccess
        };


        planBadge.classList.remove(
            "plan-pro",
            "plan-business",
            "plan-admin"
        );


        if (isAdmin) {

            planBadge.textContent =
                "ADMIN";

            planBadge.classList.add(
                "plan-admin"
            );

        } else if (hasAllAccess) {

            planBadge.textContent =
                "ALL ACCESS";

        } else if (hasBusiness) {

            planBadge.textContent =
                "BUSINESS";

            planBadge.classList.add(
                "plan-business"
            );

        } else if (hasWorkApps) {

            planBadge.textContent =
                "WORK APPS";

        } else if (hasPro) {

            planBadge.textContent =
                "PRO";

            planBadge.classList.add(
                "plan-pro"
            );

        } else {

            planBadge.textContent =
                "FREE";
        }


    } catch (error) {

        console.error(
            "User plan error:",
            error
        );

        window.jSyroAccess = {
            plan: "free",
            role: "user",
            status: "active",
            isAdmin: false,
            hasPro: false,
            hasBusiness: false,
            hasWorkApps: false,
            hasAllAccess: false
        };

        planBadge.textContent =
            "FREE";
    }
}


if (
    document.readyState ===
    "loading"
) {

    document.addEventListener(
        "DOMContentLoaded",
        initializeUserPlan
    );

} else {

    initializeUserPlan();
}

