function buildBusinessTemplateFiles({
    title,
    description,
    accent,
    homeBody,
    dashboardBody = null,
    extraPages = {},
    script = "",
    extraCss = ""
}) {

    const files = buildTemplateFiles({
        title,
        description,
        accent,
        body: homeBody,
        script,
        extraCss
    });


    function createBusinessPage(
        pageTitle,
        pageBody
    ) {

        return `<!DOCTYPE html>
<html lang="en">

<head>

    <meta charset="UTF-8">

    <meta
        name="viewport"
        content="width=device-width, initial-scale=1.0"
    >

    <title>${title} — ${pageTitle}</title>

    <link
        rel="stylesheet"
        href="style.css"
    >

</head>

<body>

${pageBody}

<script src="script.js"></script>

</body>

</html>`;
    }


    if (dashboardBody) {

        files["dashboard.html"] =
            createBusinessPage(
                "Dashboard",
                dashboardBody
            );
    }


    Object.entries(
        extraPages
    ).forEach(
        function ([fileName, page]) {

            if (!page) {
                return;
            }


            if (
                typeof page ===
                "string"
            ) {

                const pageTitle =
                    fileName
                        .replace(
                            /\.html$/i,
                            ""
                        )
                        .replace(
                            /[-_]/g,
                            " "
                        );

                files[fileName] =
                    createBusinessPage(
                        pageTitle,
                        page
                    );

                return;
            }


            files[fileName] =
                createBusinessPage(
                    page.title ||
                        fileName,
                    page.body || ""
                );
        }
    );


    return files;
}

