        script: `
const crmSearch =
    document.getElementById(
        "crmLeadSearch"
    );

if (crmSearch) {

    crmSearch.addEventListener(
        "input",
        function () {

            const value =
                crmSearch.value
                    .toLowerCase();

            document
                .querySelectorAll(
                    ".crm-lead-row"
                )
                .forEach(
                    function (row) {

                        row.style.display =
                            row.textContent
                                .toLowerCase()
                                .includes(value)
                                ? ""
                                : "none";
                    }
                );
        }
    );
}
`,

