        script: `
const stockSearch =
    document.getElementById(
        "stockSearch"
    );

if (stockSearch) {

    stockSearch.addEventListener(
        "input",
        function () {

            const value =
                stockSearch.value
                    .toLowerCase();

            document
                .querySelectorAll(
                    ".stock-product-row"
                )
                .forEach(
                    function (row) {

                        row.style.display =
                            row.textContent
                                .toLowerCase()
                                .includes(value)
                                ? ""
                                : "none";
                    }
                );
        }
    );
}
`,

