        script: `
const invoiceFilter =
    document.getElementById(
        "invoiceFilter"
    );

if (invoiceFilter) {

    invoiceFilter.addEventListener(
        "change",
        function () {

            const value =
                invoiceFilter.value;

            document
                .querySelectorAll(
                    ".fin-invoice-row"
                )
                .forEach(
                    function (row) {

                        row.style.display =
                            value === "all" ||
                            row.dataset.status ===
                                value
                                ? ""
                                : "none";
                    }
                );
        }
    );
}
`,

