        script: `
const taskChecks =
    Array.from(
        document.querySelectorAll(
            ".portal-task-check"
        )
    );

const taskProgress =
    document.getElementById(
        "taskProgress"
    );

function updateTaskProgress() {

    if (!taskProgress) {
        return;
    }

    const completed =
        taskChecks.filter(
            function (checkbox) {
                return checkbox.checked;
            }
        ).length;

    taskProgress.textContent =
        completed +
        " / " +
        taskChecks.length +
        " completed";
}

taskChecks.forEach(
    function (checkbox) {

        checkbox.addEventListener(
            "change",
            updateTaskProgress
        );
    }
);

updateTaskProgress();
`,

