        script: `
(function () {

    var search =
        document.getElementById(
            "phrEmployeeSearch"
        );

    if (search) {

        var rows =
            Array.from(
                document.querySelectorAll(
                    ".phr-employee-row"
                )
            );

        var empty =
            document.getElementById(
                "phrEmployeeEmpty"
            );

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                rows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var approve =
                event.target.closest(
                    ".phr-approve"
                );

            var decline =
                event.target.closest(
                    ".phr-decline"
                );

            if (!approve && !decline) {
                return;
            }

            var actions =
                event.target.closest(
                    ".phr-request-actions"
                );

            if (!actions) {
                return;
            }

            actions.innerHTML =
                approve
                    ? '<strong class="phr-decision ok">APPROVED</strong>'
                    : '<strong class="phr-decision no">DECLINED</strong>';
        }
    );

})();
`,

