        script: `
(function () {

    var search =
        document.getElementById(
            "rdTicketSearch"
        );

    var filter =
        document.getElementById(
            "rdTicketFilter"
        );

    var rows =
        Array.from(
            document.querySelectorAll(
                ".rd-ticket-row"
            )
        );

    function applyTicketFilters() {

        if (!rows.length) {
            return;
        }

        var query =
            search
                ? search.value
                    .trim()
                    .toLowerCase()
                : "";

        var priority =
            filter
                ? filter.value
                : "all";

        var visible = 0;

        rows.forEach(
            function (row) {

                var matchSearch =
                    (
                        row.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchPriority =
                    priority === "all" ||
                    row.dataset.priority === priority;

                row.hidden =
                    !(
                        matchSearch &&
                        matchPriority
                    );

                if (!row.hidden) {
                    visible += 1;
                }
            }
        );

        var empty =
            document.getElementById(
                "rdTicketEmpty"
            );

        if (empty) {
            empty.hidden =
                visible !== 0;
        }
    }

    if (search) {
        search.addEventListener(
            "input",
            applyTicketFilters
        );
    }

    if (filter) {
        filter.addEventListener(
            "change",
            applyTicketFilters
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".rd-resolve-btn"
                );

            if (!button) {
                return;
            }

            var row =
                button.closest(
                    ".rd-ticket-row"
                );

            if (!row) {
                return;
            }

            button.textContent =
                "Resolved";

            button.disabled = true;

            row.classList.add(
                "resolved"
            );
        }
    );

})();
`,

