        script: `
(function () {

    var search =
        document.getElementById(
            "mfOrderSearch"
        );

    if (search) {

        var rows =
            Array.from(
                document.querySelectorAll(
                    ".mf-order-row"
                )
            );

        var empty =
            document.getElementById(
                "mfOrderEmpty"
            );

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                rows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".mf-fulfill"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Fulfilled";

            button.disabled = true;

            var row =
                button.closest(
                    ".mf-order-row"
                );

            if (row) {
                row.classList.add(
                    "fulfilled"
                );
            }
        }
    );

})();
`,

