        script: `
(function () {

    var search =
        document.getElementById(
            "hvPropertySearch"
        );

    if (search) {

        var rows =
            Array.from(
                document.querySelectorAll(
                    ".hv-property-row"
                )
            );

        var empty =
            document.getElementById(
                "hvPropertyEmpty"
            );

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                rows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".hv-maint-btn"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Completed";

            button.disabled = true;

            var row =
                button.closest(
                    ".hv-maint-row"
                );

            if (row) {
                row.classList.add(
                    "completed"
                );
            }
        }
    );

})();
`,

