        script: `
(function () {

    var search =
        document.getElementById(
            "spRequestSearch"
        );

    if (search) {

        var rows =
            Array.from(
                document.querySelectorAll(
                    ".sp-request-row"
                )
            );

        var empty =
            document.getElementById(
                "spRequestEmpty"
            );

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                rows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var approve =
                event.target.closest(
                    ".sp-approve"
                );

            var reject =
                event.target.closest(
                    ".sp-reject"
                );

            if (!approve && !reject) {
                return;
            }

            var actions =
                event.target.closest(
                    ".sp-approval-actions"
                );

            if (!actions) {
                return;
            }

            actions.innerHTML =
                approve
                    ? '<strong class="sp-decision approved">APPROVED</strong>'
                    : '<strong class="sp-decision rejected">REJECTED</strong>';
        }
    );

})();
`,

