        script: `
(function () {

    var boardSearch =
        document.getElementById(
            "atsBoardSearch"
        );

    var roleFilter =
        document.getElementById(
            "atsRoleFilter"
        );

    function filterBoard() {

        var cards =
            Array.from(
                document.querySelectorAll(
                    ".ats-card"
                )
            );

        if (!cards.length) {
            return;
        }

        var query =
            boardSearch
                ? boardSearch.value
                    .trim()
                    .toLowerCase()
                : "";

        var role =
            roleFilter
                ? roleFilter.value
                : "all";

        cards.forEach(
            function (card) {

                var matchText =
                    (
                        card.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchRole =
                    role === "all" ||
                    card.dataset.role === role;

                card.hidden =
                    !(
                        matchText &&
                        matchRole
                    );
            }
        );
    }

    if (boardSearch) {
        boardSearch.addEventListener(
            "input",
            filterBoard
        );
    }

    if (roleFilter) {
        roleFilter.addEventListener(
            "change",
            filterBoard
        );
    }


    var candidateSearch =
        document.getElementById(
            "atsCandidateSearch"
        );

    if (candidateSearch) {

        var candidateRows =
            Array.from(
                document.querySelectorAll(
                    ".ats-directory-row"
                )
            );

        var candidateEmpty =
            document.getElementById(
                "atsCandidateEmpty"
            );

        candidateSearch.addEventListener(
            "input",
            function () {

                var value =
                    candidateSearch.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                candidateRows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (candidateEmpty) {
                    candidateEmpty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var stageButton =
                event.target.closest(
                    ".ats-stage-button"
                );

            if (stageButton) {

                stageButton.textContent =
                    "Moved to " +
                    stageButton.dataset.next;

                stageButton.disabled = true;

                var card =
                    stageButton.closest(
                        ".ats-card"
                    );

                if (card) {
                    card.classList.add(
                        "ats-card-moved"
                    );
                }

                return;
            }


            var offerButton =
                event.target.closest(
                    ".ats-offer-action"
                );

            if (offerButton) {
                offerButton.textContent =
                    "Updated ✓";

                offerButton.disabled = true;
            }
        }
    );

})();
`,

