        script: `
(function () {

    var search =
        document.getElementById(
            "erpPoSearch"
        );

    var status =
        document.getElementById(
            "erpPoStatus"
        );

    var rows =
        Array.from(
            document.querySelectorAll(
                ".erp-po-row"
            )
        );

    function filterRows() {

        if (!rows.length) {
            return;
        }

        var query =
            search
                ? search.value
                    .trim()
                    .toLowerCase()
                : "";

        var currentStatus =
            status
                ? status.value
                : "all";

        var visible = 0;

        rows.forEach(
            function (row) {

                var matchText =
                    (
                        row.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchStatus =
                    currentStatus === "all" ||
                    row.dataset.status ===
                        currentStatus;

                row.hidden =
                    !(
                        matchText &&
                        matchStatus
                    );

                if (!row.hidden) {
                    visible += 1;
                }
            }
        );

        var empty =
            document.getElementById(
                "erpPoEmpty"
            );

        if (empty) {
            empty.hidden =
                visible !== 0;
        }
    }

    if (search) {
        search.addEventListener(
            "input",
            filterRows
        );
    }

    if (status) {
        status.addEventListener(
            "change",
            filterRows
        );
    }


    var clear =
        document.getElementById(
            "erpClearFilters"
        );

    if (clear) {
        clear.addEventListener(
            "click",
            function () {

                if (search) {
                    search.value = "";
                }

                if (status) {
                    status.value = "all";
                }

                filterRows();
            }
        );
    }


    rows.forEach(
        function (row) {

            row.addEventListener(
                "click",
                function () {

                    rows.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    row.classList.add(
                        "active"
                    );

                    var mapping = {
                        erpDetailPo:
                            row.dataset.po,
                        erpDetailSupplier:
                            row.dataset.supplier,
                        erpDetailValue:
                            row.dataset.value,
                        erpDetailOwner:
                            row.dataset.owner,
                        erpDetailDelivery:
                            row.dataset.delivery,
                        erpDetailStatus:
                            row.dataset.statusLabel
                    };

                    Object.keys(mapping)
                        .forEach(
                            function (id) {

                                var element =
                                    document.getElementById(
                                        id
                                    );

                                if (element) {
                                    element.textContent =
                                        mapping[id];
                                }
                            }
                        );
                }
            );
        }
    );


    var approvePo =
        document.getElementById(
            "erpApprovePo"
        );

    if (approvePo) {
        approvePo.addEventListener(
            "click",
            function () {

                approvePo.textContent =
                    "Approved ✓";

                approvePo.disabled = true;

                var detailStatus =
                    document.getElementById(
                        "erpDetailStatus"
                    );

                if (detailStatus) {
                    detailStatus.textContent =
                        "Approved";
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var approve =
                event.target.closest(
                    ".erp-request-approve"
                );

            var reject =
                event.target.closest(
                    ".erp-request-reject"
                );

            if (!approve && !reject) {
                return;
            }

            var actions =
                event.target.closest(
                    ".erp-request-actions"
                );

            if (!actions) {
                return;
            }

            actions.innerHTML =
                approve
                    ? '<strong class="erp-decision approved">APPROVED</strong>'
                    : '<strong class="erp-decision rejected">REJECTED</strong>';
        }
    );

})();
`,

