        script: `
(function () {

    var search =
        document.getElementById(
            "cscAccountSearch"
        );

    var accounts =
        Array.from(
            document.querySelectorAll(
                ".csc-account"
            )
        );

    var empty =
        document.getElementById(
            "cscAccountEmpty"
        );

    if (search) {

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                accounts.forEach(
                    function (account) {

                        var match =
                            (
                                account.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        account.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    function setText(
        id,
        value
    ) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }


    accounts.forEach(
        function (account) {

            account.addEventListener(
                "click",
                function () {

                    accounts.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    account.classList.add(
                        "active"
                    );

                    setText(
                        "cscAccountName",
                        account.dataset.name
                    );

                    setText(
                        "cscAccountPlan",
                        account.dataset.plan
                    );

                    setText(
                        "cscAccountOwner",
                        account.dataset.owner
                    );

                    setText(
                        "cscHealth",
                        account.dataset.health
                    );

                    setText(
                        "cscArr",
                        account.dataset.arr
                    );

                    setText(
                        "cscRenewal",
                        account.dataset.renewal
                    );

                    setText(
                        "cscUsage",
                        account.dataset.usage
                    );

                    setText(
                        "cscSupport",
                        account.dataset.support
                    );
                }
            );
        }
    );


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".csc-review-risk"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Reviewed ✓";

            button.disabled = true;

            var row =
                button.closest(
                    "article"
                );

            if (row) {
                row.classList.add(
                    "reviewed"
                );
            }
        }
    );

})();
`,

