        script: `
(function () {

    var search =
        document.getElementById(
            "grcControlSearch"
        );

    var status =
        document.getElementById(
            "grcControlStatus"
        );

    var controls =
        Array.from(
            document.querySelectorAll(
                ".grc-control-row"
            )
        );

    function filterControls() {

        if (!controls.length) {
            return;
        }

        var query =
            search
                ? search.value
                    .trim()
                    .toLowerCase()
                : "";

        var filter =
            status
                ? status.value
                : "all";

        var visible = 0;

        controls.forEach(
            function (row) {

                var matchText =
                    (
                        row.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchStatus =
                    filter === "all" ||
                    row.dataset.status === filter;

                row.hidden =
                    !(
                        matchText &&
                        matchStatus
                    );

                if (!row.hidden) {
                    visible += 1;
                }
            }
        );

        var empty =
            document.getElementById(
                "grcControlEmpty"
            );

        if (empty) {
            empty.hidden =
                visible !== 0;
        }
    }

    if (search) {
        search.addEventListener(
            "input",
            filterControls
        );
    }

    if (status) {
        status.addEventListener(
            "change",
            filterControls
        );
    }


    function setText(
        id,
        value
    ) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }


    controls.forEach(
        function (row) {

            row.addEventListener(
                "click",
                function () {

                    controls.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    row.classList.add(
                        "active"
                    );

                    setText(
                        "grcDetailControl",
                        row.dataset.control
                    );

                    setText(
                        "grcDetailTitle",
                        row.dataset.title
                    );

                    setText(
                        "grcDetailOwner",
                        row.dataset.owner
                    );

                    setText(
                        "grcDetailEvidence",
                        row.dataset.evidence
                    );

                    setText(
                        "grcDetailTest",
                        row.dataset.test
                    );

                    setText(
                        "grcDetailResult",
                        row.dataset.result
                    );
                }
            );
        }
    );


    var markPass =
        document.getElementById(
            "grcMarkPass"
        );

    if (markPass) {

        markPass.addEventListener(
            "click",
            function () {

                setText(
                    "grcDetailResult",
                    "Passing"
                );

                markPass.textContent =
                    "Passing ✓";

                markPass.disabled = true;
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".grc-close-finding"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Closed ✓";

            button.disabled = true;

            var row =
                button.closest(
                    "article"
                );

            if (row) {
                row.classList.add(
                    "closed"
                );
            }
        }
    );

})();
`,

