        script: `
(function () {

    var search =
        document.getElementById(
            "clmSearch"
        );

    var contracts =
        Array.from(
            document.querySelectorAll(
                ".clm-contract"
            )
        );

    var empty =
        document.getElementById(
            "clmEmpty"
        );

    function setText(id, value) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }

    if (search) {

        search.addEventListener(
            "input",
            function () {

                var value =
                    search.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                contracts.forEach(
                    function (contract) {

                        var match =
                            (
                                contract.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        contract.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    contracts.forEach(
        function (contract) {

            contract.addEventListener(
                "click",
                function () {

                    contracts.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    contract.classList.add(
                        "active"
                    );

                    setText(
                        "clmDocTitle",
                        contract.dataset.title
                    );

                    setText(
                        "clmDocCompany",
                        contract.dataset.company
                    );

                    setText(
                        "clmValue",
                        contract.dataset.value
                    );

                    setText(
                        "clmOwner",
                        contract.dataset.owner
                    );

                    setText(
                        "clmRenewal",
                        contract.dataset.renewal
                    );

                    setText(
                        "clmStatus",
                        contract.dataset.status
                    );

                    setText(
                        "clmRisk",
                        contract.dataset.risk
                    );
                }
            );
        }
    );


    document.addEventListener(
        "click",
        function (event) {

            var approve =
                event.target.closest(
                    ".clm-approve"
                );

            var reject =
                event.target.closest(
                    ".clm-reject"
                );

            if (!approve && !reject) {
                return;
            }

            var actions =
                event.target.closest(
                    ".clm-review-actions"
                );

            if (!actions) {
                return;
            }

            actions.innerHTML =
                approve
                    ? '<strong class="clm-decision approved">APPROVED</strong>'
                    : '<strong class="clm-decision returned">RETURNED</strong>';
        }
    );

})();
`,

