        script: `
(function () {

    var lines =
        Array.from(
            document.querySelectorAll(
                ".mfg-line"
            )
        );

    function setText(id, value) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }

    lines.forEach(
        function (line) {

            line.addEventListener(
                "click",
                function () {

                    lines.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    line.classList.add(
                        "active"
                    );

                    setText(
                        "mfgLine",
                        line.dataset.line
                    );

                    setText(
                        "mfgProduct",
                        line.dataset.product
                    );

                    setText(
                        "mfgTarget",
                        line.dataset.target
                    );

                    setText(
                        "mfgOutput",
                        line.dataset.output
                    );

                    setText(
                        "mfgRate",
                        line.dataset.rate
                    );

                    setText(
                        "mfgStatus",
                        line.dataset.status
                    );
                }
            );
        }
    );


    var orderSearch =
        document.getElementById(
            "mfgOrderSearch"
        );

    if (orderSearch) {

        var rows =
            Array.from(
                document.querySelectorAll(
                    ".mfg-order-row"
                )
            );

        var empty =
            document.getElementById(
                "mfgOrderEmpty"
            );

        orderSearch.addEventListener(
            "input",
            function () {

                var value =
                    orderSearch.value
                        .trim()
                        .toLowerCase();

                var visible = 0;

                rows.forEach(
                    function (row) {

                        var match =
                            (
                                row.dataset.search ||
                                ""
                            )
                                .toLowerCase()
                                .includes(value);

                        row.hidden = !match;

                        if (match) {
                            visible += 1;
                        }
                    }
                );

                if (empty) {
                    empty.hidden =
                        visible !== 0;
                }
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".mfg-release"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Released ✓";

            button.disabled = true;

            var row =
                button.closest(
                    "article"
                );

            if (row) {
                row.classList.add(
                    "released"
                );
            }
        }
    );

})();
`,

