        script: `
(function () {

    var search =
        document.getElementById(
            "iamSearch"
        );

    var status =
        document.getElementById(
            "iamStatus"
        );

    var rows =
        Array.from(
            document.querySelectorAll(
                ".iam-row"
            )
        );

    var empty =
        document.getElementById(
            "iamEmpty"
        );

    function filterAssets() {

        if (!rows.length) {
            return;
        }

        var query =
            search
                ? search.value
                    .trim()
                    .toLowerCase()
                : "";

        var selected =
            status
                ? status.value
                : "all";

        var visible = 0;

        rows.forEach(
            function (row) {

                var matchText =
                    (
                        row.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchStatus =
                    selected === "all" ||
                    row.dataset.status ===
                        selected;

                row.hidden =
                    !(
                        matchText &&
                        matchStatus
                    );

                if (!row.hidden) {
                    visible += 1;
                }
            }
        );

        if (empty) {
            empty.hidden =
                visible !== 0;
        }
    }

    if (search) {
        search.addEventListener(
            "input",
            filterAssets
        );
    }

    if (status) {
        status.addEventListener(
            "change",
            filterAssets
        );
    }


    function setText(id, value) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }


    rows.forEach(
        function (row) {

            row.addEventListener(
                "click",
                function () {

                    rows.forEach(
                        function (item) {
                            item.classList.remove(
                                "active"
                            );
                        }
                    );

                    row.classList.add(
                        "active"
                    );

                    setText("iamAssetId", row.dataset.id);
                    setText("iamUser", row.dataset.name);
                    setText("iamModel", row.dataset.model);
                    setText("iamSerial", row.dataset.serial);
                    setText("iamOs", row.dataset.os);
                    setText("iamEncryption", row.dataset.encryption);
                    setText("iamCheckin", row.dataset.checkin);
                }
            );
        }
    );


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".iam-certify"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "Certified ✓";

            button.disabled = true;

            var row =
                button.closest(
                    "article"
                );

            if (row) {
                row.classList.add(
                    "certified"
                );
            }
        }
    );

})();
`,

