        script: `
(function () {

    var search =
        document.getElementById(
            "qmsSearch"
        );

    var severity =
        document.getElementById(
            "qmsSeverity"
        );

    var cases =
        Array.from(
            document.querySelectorAll(
                ".qms-case"
            )
        );

    var empty =
        document.getElementById(
            "qmsEmpty"
        );

    function filterCases() {

        if (!cases.length) {
            return;
        }

        var query =
            search
                ? search.value
                    .trim()
                    .toLowerCase()
                : "";

        var level =
            severity
                ? severity.value
                : "all";

        var visible = 0;

        cases.forEach(
            function (item) {

                var matchText =
                    (
                        item.dataset.search ||
                        ""
                    )
                        .toLowerCase()
                        .includes(query);

                var matchLevel =
                    level === "all" ||
                    item.dataset.severity === level;

                item.hidden =
                    !(
                        matchText &&
                        matchLevel
                    );

                if (!item.hidden) {
                    visible += 1;
                }
            }
        );

        if (empty) {
            empty.hidden =
                visible !== 0;
        }
    }

    if (search) {
        search.addEventListener(
            "input",
            filterCases
        );
    }

    if (severity) {
        severity.addEventListener(
            "change",
            filterCases
        );
    }


    function setText(id, value) {

        var element =
            document.getElementById(id);

        if (element) {
            element.textContent = value;
        }
    }


    cases.forEach(
        function (item) {

            item.addEventListener(
                "click",
                function () {

                    cases.forEach(
                        function (other) {
                            other.classList.remove(
                                "active"
                            );
                        }
                    );

                    item.classList.add(
                        "active"
                    );

                    setText("qmsCase", item.dataset.case);
                    setText("qmsTitle", item.dataset.title);
                    setText("qmsArea", item.dataset.area);
                    setText("qmsOwner", item.dataset.owner);
                    setText("qmsDue", item.dataset.date);
                    setText(
                        "qmsSeverityLabel",
                        item.dataset.severityLabel
                    );
                }
            );
        }
    );


    var advance =
        document.getElementById(
            "qmsAdvance"
        );

    if (advance) {

        advance.addEventListener(
            "click",
            function () {

                advance.textContent =
                    "Root Cause Completed ✓";

                advance.disabled = true;
            }
        );
    }


    document.addEventListener(
        "click",
        function (event) {

            var button =
                event.target.closest(
                    ".qms-close-capa"
                );

            if (!button) {
                return;
            }

            button.textContent =
                "CAPA Closed ✓";

            button.disabled = true;

            var row =
                button.closest(
                    "article"
                );

            if (row) {
                row.classList.add(
                    "closed"
                );
            }
        }
    );

})();
`,

