/* =========================
   INITIALIZE TEMPLATES
========================= */

function initializeTemplatesFeature() {

    const templatesButton =
        document.getElementById(
            "templatesBtn"
        );

    const templatesModal =
        document.getElementById(
            "templatesModal"
        );

    const templatesGrid =
        document.getElementById(
            "templatesGrid"
        );

    const closeButton =
        document.getElementById(
            "closeTemplatesModal"
        );

    const searchInput =
        document.getElementById(
            "templateSearchInput"
        );

    const categoryFilter =
        document.getElementById(
            "templateCategoryFilter"
        );

    const templatesLock =
        document.getElementById(
            "templatesLock"
        );


    if (
        !templatesButton ||
        !templatesModal ||
        !templatesGrid
    ) {
        console.error(
            "Templates elements were not found"
        );
        return;
    }


    if (
        templatesButton.dataset.ready ===
        "true"
    ) {
        return;
    }


    templatesButton.dataset.ready =
        "true";


    /*
     * Return the paid plan required
     * for a template.
     *
     * Main Templates:
     * - business → BUSINESS
     * - app/dashboard → WORK APPS
     * - everything else → PRO
     */

    function getTemplatePlan(template) {

        const category =
            String(
                template?.category ||
                ""
            )
                .trim()
                .toLowerCase();


        if (
            category === "business"
        ) {
            return "business";
        }


        if (
            category === "app" ||
            category === "dashboard" ||
            category === "work apps" ||
            category === "work_apps" ||
            category === "work-apps"
        ) {
            return "work";
        }


        return "pro";
    }


    function hasTemplateAccess(template) {

        const access =
            window.jSyroAccess || {};


        if (access.isAdmin) {
            return true;
        }


        if (access.hasAllAccess) {
            return true;
        }


        const requiredPlan =
            getTemplatePlan(
                template
            );


        if (
            requiredPlan === "pro" &&
            access.hasPro
        ) {
            return true;
        }


        if (
            requiredPlan === "business" &&
            access.hasBusiness
        ) {
            return true;
        }


        if (
            requiredPlan === "work" &&
            access.hasWorkApps
        ) {
            return true;
        }


        return false;
    }


    function getTemplatePaymentPlan(
        template
    ) {

        const requiredPlan =
            getTemplatePlan(
                template
            );


        if (
            requiredPlan === "business"
        ) {
            return "business";
        }


        if (
            requiredPlan === "work"
        ) {
            return "work_apps";
        }


        return "pro";
    }


    function updateTemplateAccessBadge() {

        if (!templatesLock) {
            return;
        }


        /*
         * The main Templates library can
         * always be opened.
         *
         * This badge only indicates that
         * paid templates are available
         * according to the user's plan.
         */

        const access =
            window.jSyroAccess || {};


        const hasAnyPaidAccess =
            access.isAdmin ||
            access.hasAllAccess ||
            access.hasPro ||
            access.hasBusiness ||
            access.hasWorkApps;


        templatesLock.textContent =
            hasAnyPaidAccess
                ? "OPEN"
                : "LOCKED";


        templatesLock.style.color =
            hasAnyPaidAccess
                ? "#aef2da"
                : "";


        templatesLock.style.borderColor =
            hasAnyPaidAccess
                ? "#32b988"
                : "";
    }


    function closeTemplatesModal() {

        templatesModal.classList.remove(
            "open"
        );

        templatesModal.setAttribute(
            "aria-hidden",
            "true"
        );
    }


    async function useTemplate(
        template
    ) {

        const hasAccess =
            hasTemplateAccess(
                template
            );


        /*
         * IMPORTANT:
         * Locked templates are still
         * clickable. Clicking them opens
         * the correct payment popup.
         */

        if (!hasAccess) {

            const paymentPlan =
                getTemplatePaymentPlan(
                    template
                );


            if (
                typeof openPaymentModal ===
                "function"
            ) {

                openPaymentModal(
                    paymentPlan
                );

            } else {

                showToast(
                    `${paymentPlan} plan is required to use this template.`
                );
            }

            return;
        }


        const enteredName =
            window.prompt(
                "Enter project name:",
                template.name
                    .toLowerCase()
                    .replace(
                        /\s+/g,
                        "-"
                    )
            );


        if (enteredName === null) {
            return;
        }


        const cleanName =
            enteredName
                .trim()
                .replace(
                    /[\\/:*?"<>|]/g,
                    "-"
                )
                .replace(
                    /\s+/g,
                    "-"
                );


        if (!cleanName) {

            showToast(
                "Enter a valid project name"
            );

            return;
        }


        await saveProjectToCloud();


        currentProjectKey =
            window.crypto &&
            typeof window.crypto.randomUUID ===
                "function"

                ? window.crypto.randomUUID()

                : `project-${Date.now()}`;


        localStorage.setItem(
            "j-syro-current-project-key",
            currentProjectKey
        );


        state.files =
            JSON.parse(
                JSON.stringify(
                    template.files
                )
            );


        state.folders = [];

        state.activeFile =
            "index.html";

        state.openFiles = [
            "index.html"
        ];

        state.dirty.clear();

        state.selectedFolder = "";

        state.expandedFolders =
            new Set();

        state.inlineAction = null;

        state.contextTarget = null;

        state.pendingDelete = null;


        const projectNameText =
            document.getElementById(
                "projectNameText"
            );


        if (projectNameText) {

            projectNameText.textContent =
                cleanName;
        }


        persistFiles();

        renderFiles();

        renderTabs();

        openFile(
            "index.html"
        );


        await saveProjectToCloud();


        closeTemplatesModal();


        showToast(
            `${template.name} template created`
        );
    }


    function renderTemplates() {

        const searchValue =
            searchInput
                ?.value
                .trim()
                .toLowerCase() ||
            "";


        const categoryValue =
            categoryFilter?.value ||
            "all";


        const filteredTemplates =
            jSyroTemplates.filter(
                function (template) {

                    const matchesSearch =
                        template.name
                            .toLowerCase()
                            .includes(
                                searchValue
                            ) ||
                        template.description
                            .toLowerCase()
                            .includes(
                                searchValue
                            );


                    const matchesCategory =
                        categoryValue ===
                            "all" ||
                        template.category ===
                            categoryValue;


                    return (
                        matchesSearch &&
                        matchesCategory
                    );
                }
            );


        templatesGrid.innerHTML = "";


        if (
            filteredTemplates.length ===
            0
        ) {

            templatesGrid.innerHTML =
                '<p class="panel-hint">' +
                "No templates found." +
                "</p>";

            return;
        }


        filteredTemplates.forEach(
            function (template) {

                const hasAccess =
                    hasTemplateAccess(
                        template
                    );


                const card =
                    document.createElement(
                        "article"
                    );

                card.className =
                    "template-card";


                const preview =
                    document.createElement(
                        "div"
                    );

                preview.className =
                    "template-preview";

                preview.innerHTML =
                    `<strong style="
                        font-size:42px;
                        color:#b8b1ff;
                    ">
                        ${template.icon}
                    </strong>`;


                const badge =
                    document.createElement(
                        "span"
                    );

                badge.className =
                    "template-premium-badge";

                badge.textContent =
                    hasAccess
                        ? "🔓 UNLOCKED"
                        : "🔒 LOCKED";


                preview.appendChild(
                    badge
                );


                const content =
                    document.createElement(
                        "div"
                    );

                content.className =
                    "template-card-content";


                const category =
                    document.createElement(
                        "span"
                    );

                category.className =
                    "template-category";

                category.textContent =
                    template.category;


                const title =
                    document.createElement(
                        "h3"
                    );

                title.textContent =
                    template.name;


                const description =
                    document.createElement(
                        "p"
                    );

                description.textContent =
                    template.description;


                const useButton =
                    document.createElement(
                        "button"
                    );

                useButton.type =
                    "button";

                useButton.className =
                    "template-use-button";


                useButton.textContent =
                    hasAccess
                        ? "Use Template"
                        : "🔒 Unlock Template";


                /*
                 * NEVER disable the button.
                 *
                 * Free users must be able to
                 * click it and see payment.
                 */

                useButton.disabled =
                    false;


                useButton.addEventListener(
                    "click",
                    function () {

                        useTemplate(
                            template
                        );
                    }
                );


                content.append(
                    category,
                    title,
                    description,
                    useButton
                );


                card.append(
                    preview,
                    content
                );


                templatesGrid.appendChild(
                    card
                );
            }
        );
    }


    async function openTemplatesModal() {

        if (
            typeof initializeUserPlan ===
            "function"
        ) {
            await initializeUserPlan();
        }


        updateTemplateAccessBadge();

        renderTemplates();


        templatesModal.classList.add(
            "open"
        );

        templatesModal.setAttribute(
            "aria-hidden",
            "false"
        );
    }


    templatesButton.addEventListener(
        "click",
        openTemplatesModal
    );


    closeButton?.addEventListener(
        "click",
        closeTemplatesModal
    );


    templatesModal.addEventListener(
        "click",
        function (event) {

            if (
                event.target ===
                templatesModal
            ) {
                closeTemplatesModal();
            }
        }
    );


    searchInput?.addEventListener(
        "input",
        renderTemplates
    );


    categoryFilter?.addEventListener(
        "change",
        renderTemplates
    );


    document.addEventListener(
        "keydown",
        function (event) {

            if (
                event.key ===
                "Escape"
            ) {
                closeTemplatesModal();
            }
        }
    );


    setTimeout(
        updateTemplateAccessBadge,
        1200
    );
}


if (
    document.readyState ===
    "loading"
) {

    document.addEventListener(
        "DOMContentLoaded",
        initializeTemplatesFeature
    );

} else {

    initializeTemplatesFeature();
}

/* =========================
   DUPLICATE PROJECT
========================= */

async function duplicateCurrentProject() {

    const duplicateButton =
        document.getElementById(
            "duplicateProjectBtn"
        );

    if (
        duplicateButton?.dataset.busy ===
        "true"
    ) {
        return;
    }

    duplicateButton.dataset.busy = "true";
    duplicateButton.disabled = true;


    try {

        /*
           Editor ki latest unsaved writing
           current file mein store karo.
        */

        if (
            state.activeFile &&
            typeof editor !== "undefined"
        ) {
            state.files[state.activeFile] =
                editor.value;
        }


        const projectNameText =
            document.getElementById(
                "projectNameText"
            );


        const currentProjectName =
            projectNameText?.textContent
                ?.trim() ||
            "untitled-project";


        const enteredName =
            window.prompt(
                "Enter duplicated project name:",
                `${currentProjectName}-copy`
            );


        if (enteredName === null) {
            return;
        }


        const duplicateName =
            enteredName
                .trim()
                .replace(
                    /[\\/:*?"<>|]/g,
                    "-"
                )
                .replace(
                    /\s+/g,
                    "-"
                );


        if (!duplicateName) {

            showToast(
                "Enter a valid project name"
            );

            return;
        }


        /*
           Original project pehle save hoga.
        */

        await saveProjectToCloud();


        /*
           Current files aur folders ki
           separate copy banegi.
        */

        const copiedFiles =
            JSON.parse(
                JSON.stringify(
                    state.files
                )
            );


        const copiedFolders =
            JSON.parse(
                JSON.stringify(
                    state.folders || []
                )
            );


        const copiedOpenFiles =
            Array.isArray(state.openFiles)
                ? [...state.openFiles]
                : [];


        const copiedActiveFile =
            state.activeFile;


        /*
           Duplicate ke liye new unique key.
        */

        currentProjectKey =
            window.crypto &&
            typeof window.crypto.randomUUID ===
                "function"

                ? window.crypto.randomUUID()

                : `project-${Date.now()}`;


        localStorage.setItem(
            "j-syro-current-project-key",
            currentProjectKey
        );


        /*
           Duplicated project ko workspace
           mein active karo.
        */

        state.files = copiedFiles;

        state.folders = copiedFolders;

        state.openFiles =
            copiedOpenFiles.filter(
                function (fileName) {

                    return (
                        state.files[fileName] !==
                        undefined
                    );
                }
            );


        state.activeFile =
            copiedActiveFile &&
            state.files[copiedActiveFile] !==
                undefined

                ? copiedActiveFile

                : (
                    state.files["index.html"] !==
                    undefined

                        ? "index.html"

                        : (
                            Object.keys(
                                state.files
                            )[0] || null
                        )
                );


        if (
            state.activeFile &&
            !state.openFiles.includes(
                state.activeFile
            )
        ) {
            state.openFiles.push(
                state.activeFile
            );
        }


        state.dirty.clear();

        state.selectedFolder = "";

        state.expandedFolders =
            new Set();


        if (projectNameText) {

            projectNameText.textContent =
                duplicateName;
        }


        persistFiles();

        renderFiles();

        renderTabs();


        if (state.activeFile) {

            openFile(
                state.activeFile
            );
        }


        /*
           Duplicate project Supabase
           mein new project ban kar save hoga.
        */

        await saveProjectToCloud();


        showToast(
            `${duplicateName} duplicated successfully`
        );

    } catch (error) {

        console.error(
            "Duplicate project error:",
            error
        );


        showToast(
            "Project could not be duplicated"
        );

    } finally {

        duplicateButton.dataset.busy =
            "false";

        duplicateButton.disabled =
            false;
    }
}


const duplicateProjectButton =
    document.getElementById(
        "duplicateProjectBtn"
    );


if (
    duplicateProjectButton &&
    duplicateProjectButton.dataset.ready !==
        "true"
) {

    duplicateProjectButton.dataset.ready =
        "true";


    duplicateProjectButton.addEventListener(
        "click",
        duplicateCurrentProject
    );
}
