    /* =========================
       LOAD VERSION HISTORY
    ========================= */

    async function loadProjectHistory() {

        showHistoryMessage(
            "Loading versions...",
            "Please wait while version history is loaded."
        );


        try {

            const {
                user,
                project
            } =
                await ensureHistoryProject(
                    false
                );


            const {
                data: versions,
                error
            } =
                await workspaceSupabase
                    .from(
                        "project_versions"
                    )
                    .select(`
                        id,
                        version_number,
                        project_name,
                        files,
                        folders,
                        created_at
                    `)
                    .eq(
                        "project_id",
                        project.id
                    )
                    .eq(
                        "user_id",
                        user.id
                    )
                    .order(
                        "version_number",
                        {
                            ascending:
                                false
                        }
                    );


            if (error) {
                throw error;
            }


            renderHistoryVersions(
                versions || []
            );

        } catch (error) {

            console.error(
                "Version history load error:",
                error
            );


            showHistoryMessage(
                "History could not be loaded",
                error.message ||
                "Please try again."
            );
        }
    }


    /* =========================
       CREATE NEW VERSION
    ========================= */

    async function createProjectVersion() {

        if (
            createVersionButton
                ?.dataset.busy ===
            "true"
        ) {
            return;
        }


        const originalText =
            createVersionButton
                ?.textContent ||
            "Save Current Version";


        if (createVersionButton) {

            createVersionButton.dataset.busy =
                "true";

            createVersionButton.disabled =
                true;

            createVersionButton.textContent =
                "Saving Version...";
        }


        try {

            const {
                user,
                project
            } =
                await ensureHistoryProject(
                    true
                );


            const {
                data: latestVersion,
                error: latestError
            } =
                await workspaceSupabase
                    .from(
                        "project_versions"
                    )
                    .select(
                        "version_number"
                    )
                    .eq(
                        "project_id",
                        project.id
                    )
                    .eq(
                        "user_id",
                        user.id
                    )
                    .order(
                        "version_number",
                        {
                            ascending:
                                false
                        }
                    )
                    .limit(1)
                    .maybeSingle();


            if (latestError) {
                throw latestError;
            }


            const nextVersionNumber =
                (
                    latestVersion
                        ?.version_number ||
                    0
                ) + 1;


            const filesSnapshot =
                JSON.parse(
                    JSON.stringify(
                        state.files ||
                        {}
                    )
                );


            const foldersSnapshot =
                JSON.parse(
                    JSON.stringify(
                        state.folders ||
                        []
                    )
                );


            const {
                error
            } =
                await workspaceSupabase
                    .from(
                        "project_versions"
                    )
                    .insert(
                        {
                            project_id:
                                project.id,

                            user_id:
                                user.id,

                            version_number:
                                nextVersionNumber,

                            project_name:
                                getCurrentProjectName(),

                            files:
                                filesSnapshot,

                            folders:
                                foldersSnapshot
                        }
                    );


            if (error) {
                throw error;
            }


            showToast(
                `Version ${nextVersionNumber} saved`
            );


            await loadProjectHistory();

        } catch (error) {

            console.error(
                "Version save error:",
                error
            );


            showToast(
                error.message ||
                "Version could not be saved"
            );

        } finally {

            if (createVersionButton) {

                createVersionButton.dataset.busy =
                    "false";

                createVersionButton.disabled =
                    false;

                createVersionButton.textContent =
                    originalText;
            }
        }
    }
    /* =========================
   AUTO SAVE HISTORY VERSION
========================= */

let autoHistorySaving =
    false;


async function createAutomaticHistoryVersion() {

    if (autoHistorySaving) {
        return;
    }


    autoHistorySaving =
        true;


    try {

        const {
            user,
            project
        } =
            await ensureHistoryProject(
                true
            );


        /* Latest version check */

        const {
            data: latestVersion,
            error: latestError
        } =
            await workspaceSupabase
                .from(
                    "project_versions"
                )
                .select(
                    `
                    version_number,
                    project_name,
                    files,
                    folders
                    `
                )
                .eq(
                    "project_id",
                    project.id
                )
                .eq(
                    "user_id",
                    user.id
                )
                .order(
                    "version_number",
                    {
                        ascending:
                            false
                    }
                )
                .limit(1)
                .maybeSingle();


        if (latestError) {
            throw latestError;
        }


        const currentName =
            getCurrentProjectName();


        const filesSnapshot =
            JSON.parse(
                JSON.stringify(
                    state.files || {}
                )
            );


        const foldersSnapshot =
            JSON.parse(
                JSON.stringify(
                    state.folders || []
                )
            );


        /* =========================
           DUPLICATE CHECK
        ========================= */

        if (latestVersion) {

            const sameName =
                latestVersion.project_name ===
                currentName;


            const sameFiles =
                JSON.stringify(
                    latestVersion.files || {}
                ) ===
                JSON.stringify(
                    filesSnapshot
                );


            const sameFolders =
                JSON.stringify(
                    latestVersion.folders || []
                ) ===
                JSON.stringify(
                    foldersSnapshot
                );


            if (
                sameName &&
                sameFiles &&
                sameFolders
            ) {

                console.log(
                    "History unchanged - snapshot skipped"
                );

                return;
            }
        }


        const nextVersionNumber =
            (
                latestVersion
                    ?.version_number ||
                0
            ) + 1;


        const {
            error
        } =
            await workspaceSupabase
                .from(
                    "project_versions"
                )
                .insert(
                    {
                        project_id:
                            project.id,

                        user_id:
                            user.id,

                        version_number:
                            nextVersionNumber,

                        project_name:
                            currentName,

                        files:
                            filesSnapshot,

                        folders:
                            foldersSnapshot
                    }
                );


        if (error) {
            throw error;
        }


        console.log(
            `Automatic history version ${nextVersionNumber} saved`
        );


        /*
         History modal open ho to
         list immediately refresh karo
        */

        if (
            !historyModal.hidden
        ) {

            await loadProjectHistory();
        }


    } catch (error) {

        console.error(
            "Automatic history save error:",
            error
        );

    } finally {

        autoHistorySaving =
            false;
    }
}

window.createAutomaticHistoryVersion =
    createAutomaticHistoryVersion;



